$catalog$::jsonb) as c (
  id text,
  primary_muscle text,
  category text,
  mechanic text,
  muscle_group text,
  prescription_type text,
  default_duration_seconds integer,
  recommended_sets smallint,
  reps_min smallint,
  reps_max smallint,
  rest_seconds smallint,
  required_equipment text[],
  locations text[],
  alternatives text[],
  source_ref text,
  merged_into text
)
left join public.exercise_library as survivor on survivor.id = c.merged_into
where e.id = c.id;

-- Saved plans, workout sessions and personal records follow a merged duplicate to its survivor.
update public.workout_plan_exercises as t
set exercise_id = e.merged_into
from public.exercise_library as e
where t.exercise_id = e.id and e.merged_into is not null;

update public.workout_session_exercises as t
set exercise_id = e.merged_into
from public.exercise_library as e
where t.exercise_id = e.id and e.merged_into is not null;

update public.personal_records as t
set exercise_id = e.merged_into
from public.exercise_library as e
where t.exercise_id = e.id and e.merged_into is not null;
